from pathlib import Path

ROOT=Path('unified-scanner/app/src/main/java/com/suhas/nseunifiedscanner')
TEST=Path('unified-scanner/app/src/test/java/com/suhas/nseunifiedscanner')

def rep(path,old,new):
    p=Path(path);s=p.read_text()
    if old not in s: raise SystemExit(f'v1.6 anchor missing in {p}: {old[:180]!r}')
    p.write_text(s.replace(old,new,1))

def opt(path,old,new):
    p=Path(path);s=p.read_text()
    if old in s:p.write_text(s.replace(old,new,1))

sp=ROOT/'ScannerEngine.java'; lp=ROOT/'LearningStore.java'; lip=ROOT/'LearningInsights.java'; mp=ROOT/'MainActivity.java'; up=ROOT/'UnifiedService.java'; gp=Path('unified-scanner/app/build.gradle')

logic='''package com.suhas.nseunifiedscanner;\n\n/** Pure deterministic pre-spike pressure classifier used by ScannerEngine and unit tests. */\nfinal class PreSpikeLogic {\n    private PreSpikeLogic(){}\n    static Assessment assess(double price3,double price5,double extension10,double lastRange,double dayPct,double vwapDist,double volAccel,double rsi,boolean macdAccel,boolean higherLows,double compression,double microBreakout){\n        boolean late = price3>=1.05 || price5>=1.45 || extension10>=1.90 || lastRange>=1.10 || dayPct>=4.0 || vwapDist>=1.90;\n        double p=28.0;\n        p+=Math.min(22.0,Math.max(0.0,(volAccel-0.90)*18.0));\n        p+=Math.max(0.0,14.0-Math.abs(rsi-56.0)*1.10);\n        p+=macdAccel?11.0:0.0;\n        p+=higherLows?9.0:0.0;\n        p+=compression>=0.12&&compression<=0.95?10.0:compression<=1.25?5.0:0.0;\n        p+=vwapDist>=-0.20&&vwapDist<=0.80?9.0:vwapDist<=1.15?4.0:0.0;\n        p+=microBreakout>=-0.18&&microBreakout<=0.28?8.0:0.0;\n        if(price5>0.90)p-=12.0;if(price3>0.65)p-=8.0;if(dayPct>3.0)p-=10.0;if(late)p-=42.0;\n        p=Math.max(0.0,Math.min(99.0,p));\n        boolean quietPrice=price5>=-0.45&&price5<=0.90&&price3<=0.70;\n        boolean pre=!late && p>=66.0 && volAccel>=1.12 && rsi>=47.0&&rsi<=68.0 && quietPrice && vwapDist>=-0.25&&vwapDist<=1.15 && (macdAccel||higherLows);\n        return new Assessment(p,pre,late);\n    }\n    static final class Assessment{final double pressure;final boolean preSpike,lateSpike;Assessment(double p,boolean pre,boolean late){pressure=p;preSpike=pre;lateSpike=late;}}\n}\n'''
(ROOT/'PreSpikeLogic.java').write_text(logic)

test='''package com.suhas.nseunifiedscanner;\nimport org.junit.Test;\nimport static org.junit.Assert.*;\npublic class PreSpikeLogicTest {\n @Test public void quietVolumeBuildQualifiesEarly(){PreSpikeLogic.Assessment a=PreSpikeLogic.assess(0.18,0.34,0.55,0.32,0.65,0.28,1.85,55,true,true,0.48,-0.05);assertTrue(a.preSpike);assertFalse(a.lateSpike);assertTrue(a.pressure>=66);}\n @Test public void verticalFiveMinuteSpikeIsLate(){PreSpikeLogic.Assessment a=PreSpikeLogic.assess(1.25,1.90,2.20,1.30,5.20,2.10,3.0,71,true,true,1.8,0.7);assertTrue(a.lateSpike);assertFalse(a.preSpike);}\n @Test public void weakVolumeDoesNotQualify(){PreSpikeLogic.Assessment a=PreSpikeLogic.assess(0.10,0.20,0.30,0.25,0.30,0.10,0.88,54,true,true,0.40,-0.10);assertFalse(a.preSpike);}\n @Test public void alreadyExtendedFromVwapIsLate(){PreSpikeLogic.Assessment a=PreSpikeLogic.assess(0.30,0.60,1.30,0.40,2.40,2.05,1.9,60,true,true,0.50,0.05);assertTrue(a.lateSpike);assertFalse(a.preSpike);}\n}\n'''
(TEST/'PreSpikeLogicTest.java').write_text(test)

