method='''\n    private void applyPreSpike(FeatureCandidate f,List<GrowwApi.Candle> c){\n        int n=c==null?0:c.size();if(n<24)return;double[] close=new double[n],high=new double[n],low=new double[n],vol=new double[n];for(int i=0;i<n;i++){GrowwApi.Candle x=c.get(i);close[i]=x.close;high[i]=x.high;low[i]=x.low;vol[i]=x.volume;}\n        double price3=(close[n-1]/close[Math.max(0,n-4)]-1.0)*100.0;double price5=(close[n-1]/close[Math.max(0,n-6)]-1.0)*100.0;double extension10=(close[n-1]/close[Math.max(0,n-11)]-1.0)*100.0;\n        double recent=0;for(int i=n-3;i<n;i++)recent+=vol[i];recent/=3.0;double base=0;int bc=0;for(int i=Math.max(0,n-15);i<n-3;i++){base+=vol[i];bc++;}base=bc>0?base/bc:0;double volAccel=base>0?recent/base:0;\n        double ch=-Double.MAX_VALUE,cl=Double.MAX_VALUE;for(int i=Math.max(0,n-13);i<n-2;i++){ch=Math.max(ch,high[i]);cl=Math.min(cl,low[i]);}double compression=(ch>0&&cl<Double.MAX_VALUE)?(ch/cl-1.0)*100.0:9;\n        double lastRange=(high[n-1]/Math.max(0.01,low[n-1])-1.0)*100.0;double vwapDist=(f.entry/f.vwap-1.0)*100.0;double microHigh=0;for(int i=Math.max(0,n-18);i<n-2;i++)microHigh=Math.max(microHigh,high[i]);double microBreakout=microHigh>0?(close[n-1]/microHigh-1.0)*100.0:0;\n        double rsi1=Indicators.rsi(close,14);Indicators.Macd m1=Indicators.macd(close);boolean macdAccel=m1.hist>=m1.prevHist;boolean higherLows=low[n-1]>=low[n-3]&&low[n-3]>=low[n-5];\n        PreSpikeLogic.Assessment a=PreSpikeLogic.assess(price3,price5,extension10,lastRange,f.dayPct,vwapDist,volAccel,rsi1,macdAccel,higherLows,compression,microBreakout);\n        f.earlyPressure=a.pressure;f.preSpike=a.preSpike;f.lateSpike=a.lateSpike;f.price3mPct=price3;f.price5mPct=price5;f.extension10mPct=extension10;f.volumeAccel=volAccel;f.compressionPct=compression;f.microBreakoutPct=microBreakout;f.rsi1m=rsi1;f.macd1mAccel=macdAccel;f.higherLows=higherLows;\n    }\n\n'''
rep(sp,'\n    private Recommendation score(FeatureCandidate f,double breadth,int minScore,int modelN){',method+'    private Recommendation score(FeatureCandidate f,double breadth,int minScore,int modelN){')

old='''double indicativeTarget=GrowwApi.roundToTick(entry*1.0070,f.instrument.tick,true);\n        // v1.5: weak breadth must not automatically kill strong individual leaders.\n        double relFloor=breadth>=58.0?1.10:(breadth<40.0?1.18:1.15);\n        double momFloor=breadth>=58.0?0.20:(breadth<40.0?0.25:0.28);\n        double spreadFloor=0.20;\n        boolean structuralRoom=roomR2>=0.35||f.breakoutConfirmed||f.freshHodPressure;\n        boolean momentumHard=entry>f.vwap && f.rsi>=52 && f.rsi<=74 && f.relVol>=relFloor && f.macd.hist>0 && f.macd.hist>=f.macd.prevHist && f.oneHour>=momFloor && f.oneHour<=4.5 && spreadPct<=spreadFloor && turnover>=75_000_000d && structuralRoom && circuitRoom>=0.80;\n        boolean recoveryClassic=entry>f.vwap && TradeSetupLogic.recoverySetup(f.crossedGreen,f.recoveryPct,f.fromOpenPct,f.rsi,f.relVol,f.macd.hist,f.macd.prevHist,f.oneHour,spreadPct,turnover,roomR2,circuitRoom,breadth,depthRatio);\n        boolean recoveryFast=entry>=f.vwap*0.999 && f.crossedGreen && f.recoveryPct>=1.10 && f.recoveryPct<=9.0 && f.fromOpenPct>=0.15 && f.rsi>=50 && f.rsi<=72 && f.relVol>=1.05 && (f.macd.hist>0||f.macd.hist>=f.macd.prevHist) && f.oneHour>=0.05 && spreadPct<=0.20 && turnover>=75_000_000d && structuralRoom && circuitRoom>=0.80 && (breadth>=30.0||depthRatio>=0.56);\n        boolean recoveryHard=recoveryClassic||recoveryFast;\n        boolean volumeIgnitionHard=entry>=f.vwap*0.999 && TradeSetupLogic.volumeIgnitionSetup(f.rsi,f.relVol,f.macd.hist,f.macd.prevHist,f.oneHour,spreadPct,turnover,Math.max(roomR2,0.68),circuitRoom,breadth,depthRatio,f.wickRatio);\n        boolean relativeStrengthHard=breadth<48.0 && f.dayPct>=0.75 && entry>=f.vwap*1.0005 && f.rsi>=52 && f.rsi<=74 && f.relVol>=1.05 && (f.macd.hist>0||f.macd.hist>=f.macd.prevHist) && f.oneHour>=0.12 && spreadPct<=0.20 && turnover>=100_000_000d && structuralRoom && circuitRoom>=0.80 && depthRatio>=0.48;\n        boolean vwapTrendHard=entry>=f.vwap*1.0010 && f.rsi>=52 && f.rsi<=72 && f.relVol>=1.10 && f.macd.hist>=f.macd.prevHist && f.oneHour>=0.18 && spreadPct<=0.18 && turnover>=100_000_000d && structuralRoom && circuitRoom>=0.80 && depthRatio>=0.50;\n        boolean clearPath=TradeSetupLogic.clearPath(entry,indicativeTarget,f.sessionHod,f.hodRejected,f.breakoutConfirmed,f.freshHodPressure);\n        boolean hard=(momentumHard||recoveryHard||volumeIgnitionHard||relativeStrengthHard||vwapTrendHard)&&clearPath;\n        double liquidity=Math.min(1.0,turnover/300_000_000d); double market=AdaptiveModel.clamp((breadth-40)/35.0,0,1);'''
new='''double indicativeTarget=GrowwApi.roundToTick(entry*1.0048,f.instrument.tick,true);\n        double spreadFloor=0.20;boolean structuralRoom=roomR2>=0.22||f.breakoutConfirmed||f.freshHodPressure;\n        boolean microReady=f.preSpike&&f.earlyPressure>=66.0&&!f.lateSpike;\n        boolean preSpikeHard=microReady && entry>=f.vwap*0.9975 && f.rsi>=48 && f.rsi<=70 && f.relVol>=0.90 && f.volumeAccel>=1.12 && spreadPct<=spreadFloor && turnover>=60_000_000d && structuralRoom && circuitRoom>=0.65 && depthRatio>=0.44;\n        boolean recoveryHard=microReady && f.crossedGreen && f.recoveryPct>=0.80 && f.fromOpenPct>=-0.10 && spreadPct<=0.20 && turnover>=60_000_000d && (breadth>=28.0||depthRatio>=0.52);\n        boolean volumeBuildHard=microReady && f.volumeAccel>=1.45 && f.rsi1m>=49&&f.rsi1m<=67 && f.macd1mAccel && spreadPct<=0.20 && turnover>=60_000_000d;\n        boolean relativeStrengthHard=microReady && breadth<48.0 && f.dayPct>=0.25 && f.dayPct<=3.0 && f.oneHour>=-0.05 && depthRatio>=0.48 && turnover>=80_000_000d;\n        boolean clearPath=TradeSetupLogic.clearPath(entry,indicativeTarget,f.sessionHod,f.hodRejected,f.breakoutConfirmed,f.freshHodPressure);\n        boolean hard=(preSpikeHard||recoveryHard||volumeBuildHard||relativeStrengthHard)&&clearPath&&!f.lateSpike;\n        double liquidity=Math.min(1.0,turnover/300_000_000d); double market=AdaptiveModel.clamp((breadth-40)/35.0,0,1);'''
